"use client"

import * as React from "react"
import { CircleCheck } from "lucide-react"
import { motion, useReducedMotion } from "motion/react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridContainer,
  GridSection,
  GridSeparator,
} from "@/components/ui/grid-layout/grid-layout"
import {
  DEFAULT_DOMAIN_SUGGESTIONS,
  DEFAULT_LABELS,
  findMailProvider,
  formatLabel,
  matchDomainSuggestions,
} from "./config"
import { createEmailSchema } from "./schemas"
import { Auth08EmailStep, Auth08SentStep } from "./steps"
import type { Auth08MailProvider, Auth08Props, Auth08Step } from "./types"
import { useAsyncAction } from "./use-auth-form"

/** 邮箱免密登录：只填邮箱，靠邮件里的登录链接或验证码登录；真实发信与认证由回调接入。 */
function Auth08({
  onSendLink,
  onVerifyCode,
  onSuccess,
  onAlternative,
  brand,
  codeLength = 6,
  resendSeconds = 60,
  domainSuggestions = DEFAULT_DOMAIN_SUGGESTIONS,
  mailProviders,
  labels: labelsProp,
  step: stepProp,
  defaultStep = "email",
  onStepChange,
  className,
  ...props
}: Auth08Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const [step, setStep] = useControllableState<Auth08Step>({
    prop: stepProp,
    defaultProp: defaultStep,
    onChange: onStepChange,
  })
  const [email, setEmail] = React.useState("")
  const [emailError, setEmailError] = React.useState("")
  const [sentEmail, setSentEmail] = React.useState("")
  const [code, setCode] = React.useState("")
  const [resent, setResent] = React.useState(false)
  const [success, setSuccess] = React.useState(false)
  // 首屏不做入场动画（无 JS 时内容也必须可见），之后每次切换才淡入位移
  const [animate, setAnimate] = React.useState(false)
  const [deadline, setDeadline] = React.useState(0)
  const [remaining, setRemaining] = React.useState(0)
  const sending = useAsyncAction(labels.failed)
  const verifying = useAsyncAction(labels.failed)
  const titleRef = React.useRef<HTMLHeadingElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const reduced = useReducedMotion()
  const length = Math.max(1, Math.min(12, Math.floor(codeLength) || 6))
  const pending = sending.pending || verifying.pending
  // 受控进入 sent 但还没有发过邮件时，退回邮箱状态
  const view: Auth08Step = step === "sent" && !sentEmail ? "email" : step
  const state = success ? "success" : view
  const previous = React.useRef(state)
  React.useEffect(() => {
    if (previous.current !== state) titleRef.current?.focus()
    previous.current = state
  }, [state])
  React.useEffect(() => {
    if (!deadline) return
    const tick = () =>
      setRemaining(Math.max(0, Math.ceil((deadline - Date.now()) / 1000)))
    tick()
    const timer = window.setInterval(tick, 250)
    return () => window.clearInterval(timer)
  }, [deadline])

  const counting = remaining > 0
  const sameAsSent = sentEmail !== "" && normalize(email) === sentEmail

  function go(next: Auth08Step) {
    setAnimate(true)
    setStep(next)
  }
  function normalize(value: string) {
    const parsed = createEmailSchema(labels).safeParse(value)
    return parsed.success ? parsed.data : ""
  }
  async function send(target: string) {
    const ok = await sending.run(() => onSendLink(target))
    if (!ok) return false
    setSentEmail(target)
    setCode("")
    verifying.setError("")
    const seconds = Math.max(0, resendSeconds)
    setRemaining(seconds)
    // 仅在发送成功的事件回调中读取时间，不参与服务端渲染。
    // eslint-disable-next-line react-hooks/purity
    setDeadline(Date.now() + seconds * 1000)
    return true
  }
  async function submitEmail() {
    if (pending) return
    const parsed = createEmailSchema(labels).safeParse(email)
    if (!parsed.success) {
      setEmailError(parsed.error.issues[0]?.message ?? labels.emailError)
      inputRef.current?.focus()
      return
    }
    setEmail(parsed.data)
    // 倒计时内换回同一个邮箱：不重发，直接回到已发送状态
    if (counting && parsed.data === sentEmail) {
      go("sent")
      return
    }
    setResent(false)
    if (await send(parsed.data)) go("sent")
  }
  async function resend() {
    if (pending || counting || !sentEmail) return
    setResent(false)
    if (await send(sentEmail)) setResent(true)
  }
  async function verify(value: string) {
    if (!onVerifyCode || pending || success || value.length !== length) return
    const ok = await verifying.run(() =>
      onVerifyCode({ email: sentEmail, code: value }),
    )
    if (ok) {
      setAnimate(true)
      setSuccess(true)
      onSuccess?.()
    }
  }
  function changeEmail() {
    setCode("")
    setResent(false)
    verifying.setError("")
    sending.setError("")
    go("email")
  }

  return (
    <div
      data-slot="auth-08"
      data-step={view}
      data-state={success ? "success" : "idle"}
      className={cn(
        "w-full overflow-x-clip bg-background text-foreground",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-md">
        {brand && (
          <GridSection
            data-slot="auth-08-brand"
            topLine
            className="flex items-center gap-2 px-4 py-4 text-sm font-medium sm:px-6"
          >
            {brand.logo}
            {brand.name}
          </GridSection>
        )}
        <GridSection topLine={!brand} className="px-4 py-8 sm:px-6">
          <motion.div
            key={state}
            data-slot="auth-08-step"
            initial={animate && !reduced ? { opacity: 0, y: 8 } : false}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: reduced ? 0 : 0.22, ease: "easeOut" }}
          >
            {success ? (
              <div className="flex flex-col items-center py-6 text-center">
                <span className="flex size-11 items-center justify-center rounded-full border border-edge bg-muted/50 text-primary [&_svg]:size-5">
                  <CircleCheck aria-hidden="true" />
                </span>
                <h1
                  ref={titleRef}
                  tabIndex={-1}
                  className="mt-4 text-2xl font-semibold tracking-tight outline-none focus-visible:underline focus-visible:underline-offset-4"
                >
                  {labels.success}
                </h1>
                <p role="status" className="mt-2 text-sm text-muted-foreground">
                  {labels.successDescription}
                </p>
              </div>
            ) : view === "email" ? (
              <Auth08EmailStep
                labels={labels}
                titleRef={titleRef}
                inputRef={inputRef}
                email={email}
                error={emailError || sending.error}
                pending={pending}
                suggestions={matchDomainSuggestions(email, domainSuggestions)}
                submitLabel={
                  sending.pending
                    ? labels.sending
                    : counting && sameAsSent
                      ? labels.viewSent
                      : labels.send
                }
                submitDisabled={pending}
                onEmailChange={(value) => {
                  setEmail(value)
                  setEmailError("")
                  sending.setError("")
                }}
                onPick={(value) => {
                  setEmail(value)
                  setEmailError("")
                  sending.setError("")
                  // 键盘按下小按钮时焦点在按钮上，补全后交回输入框，可直接回车提交
                  requestAnimationFrame(() => inputRef.current?.focus())
                }}
                onSubmit={() => void submitEmail()}
              />
            ) : (
              <Auth08SentStep
                labels={labels}
                titleRef={titleRef}
                email={sentEmail}
                provider={findMailProvider(sentEmail, mailProviders)}
                showCode={!!onVerifyCode}
                codeLength={length}
                code={code}
                codeError={verifying.error}
                verifying={verifying.pending}
                resendError={sending.error}
                resendNotice={resent}
                resendLabel={
                  sending.pending
                    ? labels.sending
                    : counting
                      ? formatLabel(labels.countdown, { seconds: remaining })
                      : labels.resend
                }
                resendDisabled={pending || counting}
                pending={pending}
                onCodeChange={(value) => {
                  setCode(value)
                  verifying.setError("")
                }}
                onCodeComplete={(value) => void verify(value)}
                onChangeEmail={changeEmail}
                onResend={() => void resend()}
              />
            )}
          </motion.div>
        </GridSection>
        {onAlternative && !success && (
          <>
            <GridSeparator />
            <GridSection className="px-4 py-4 text-center sm:px-6">
              <Button
                type="button"
                variant="link"
                size="lg"
                onClick={() => onAlternative("password")}
              >
                {labels.alternative}
              </Button>
            </GridSection>
          </>
        )}
      </GridContainer>
    </div>
  )
}

export { Auth08 }
export type { Auth08MailProvider, Auth08Props, Auth08Step }
export type { Auth08Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"

import * as React from "react"
import { Auth08 } from "@/components/auth-08/auth-08"

const wait = () => new Promise((resolve) => setTimeout(resolve, 350))

/** 演示后端仅用于体验界面，接入时替换为真实的发信与认证服务。 */
export default function LoginPage() {
  const [notice, setNotice] = React.useState("")
  return (
    <main
      data-slot="auth-08-demo"
      className="flex min-h-screen flex-col justify-center bg-background px-4 py-8 text-foreground"
    >
      <p className="mb-4 text-center text-xs text-muted-foreground">
        演示验证码：123456 · 以 blocked@ 开头的邮箱模拟发送太频繁
      </p>
      <Auth08
        brand={{
          name: "云间工作台",
          logo: (
            <span
              aria-hidden="true"
              className="flex size-6 items-center justify-center rounded-md bg-primary text-xs font-semibold text-primary-foreground"
            >
              云
            </span>
          ),
        }}
        onSendLink={async (email) => {
          await wait()
          if (email.startsWith("blocked@"))
            throw new Error("发送太频繁，请稍后再试")
        }}
        onVerifyCode={async ({ code }) => {
          await wait()
          if (code !== "123456") throw new Error("验证码错误，请重新输入")
        }}
        onSuccess={() => setNotice("已登录，接入后在这里跳转")}
        onAlternative={() => setNotice("请在接入后打开账号密码登录页面")}
      />
      <p
        role="status"
        className="mt-4 text-center text-xs text-muted-foreground"
      >
        {notice}
      </p>
    </main>
  )
}

import { z } from "zod"
import type { Auth08Labels } from "./config"

/** 去掉首尾空格，并把 @ 之后的域名转小写（名字部分保持原样） */
function createEmailSchema(labels: Auth08Labels) {
  return z
    .string()
    .trim()
    .min(1, labels.emailRequired)
    .regex(/^[^\s@]+@[^\s@]+\.[^\s@.]{2,}$/, labels.emailError)
    .transform((value) => {
      const at = value.lastIndexOf("@")
      return value.slice(0, at) + value.slice(at).toLowerCase()
    })
}

export { createEmailSchema }

import type * as React from "react"
import type { Auth08Labels } from "./config"

type Auth08Step = "email" | "sent"

/** 网页邮箱入口：邮箱域名命中 `domains` 时显示「打开 {name}」 */
type Auth08MailProvider = {
  /** 按钮里显示的名称，如「QQ 邮箱」 */
  name: string
  /** 小写域名，如 `["qq.com", "foxmail.com"]` */
  domains: string[]
  /** 网页邮箱地址，新标签页打开 */
  url: string
}

type Auth08Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 发送登录邮件，失败时抛出 Error；邮箱已去掉首尾空格、域名已转小写。 */
  onSendLink: (email: string) => Promise<void>
  /** 校验邮件里的验证码，失败时抛出 Error；不传时不显示验证码输入。 */
  onVerifyCode?: (values: { email: string; code: string }) => Promise<void>
  /** 验证码校验成功后的通知。 */
  onSuccess?: () => void
  /** 其他登录入口，由接入方处理导航；不传时不显示底部链接。 */
  onAlternative?: (method: "password") => void
  /** 品牌名称和标志，显示在顶部且切换状态时不动。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 验证码位数，限制在 1–12。@default 6 */
  codeLength?: number
  /** 重发间隔秒数。@default 60 */
  resendSeconds?: number
  /**
   * 输入到「名字@」时给出的后缀小按钮；传空数组关闭。
   * @default ["qq.com", "163.com", "gmail.com", "outlook.com"]
   */
  domainSuggestions?: string[]
  /** 追加或覆盖网页邮箱入口，排在内置表之前，同一域名以这里为准。 */
  mailProviders?: Auth08MailProvider[]
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth08Labels>
  /** 受控状态。 */
  step?: Auth08Step
  /** 初始状态。@default "email" */
  defaultStep?: Auth08Step
  /** 状态变化通知。 */
  onStepChange?: (step: Auth08Step) => void
}

export type { Auth08MailProvider, Auth08Props, Auth08Step }

import type { Auth08MailProvider } from "./types"

const DEFAULT_LABELS = {
  /** 邮箱状态的标题，切换状态时焦点落在这里 */
  title: "邮箱登录",
  description: "我们会给你发一封带登录链接的邮件，不用记密码",
  email: "邮箱",
  emailPlaceholder: "name@example.com",
  emailRequired: "请输入邮箱",
  emailError: "邮箱格式不正确，请检查后重试",
  /** 后缀小按钮这一组的读屏名称 */
  suggestions: "常用邮箱后缀",
  send: "发送登录链接",
  sending: "发送中…",
  /** 同一个邮箱在倒计时内再次提交时，直接回到已发送状态 */
  viewSent: "回到已发送的邮件",
  sentTitle: "去邮箱查收",
  /** {email} 会替换成等宽字体显示的邮箱 */
  sentTo: "登录链接已发送至 {email}",
  changeEmail: "换一个邮箱",
  /** {name} 为邮箱服务名，如「QQ 邮箱」 */
  openMail: "打开 {name}",
  newTab: "（在新标签页打开）",
  /** 有「打开邮箱」按钮时的分隔文字 */
  codeDivider: "或输入邮件里的验证码",
  /** 没有「打开邮箱」按钮时的分隔文字 */
  codeDividerSolo: "也可以输入邮件里的验证码",
  code: "验证码，共 {length} 位",
  verifying: "验证中…",
  resend: "重新发送",
  countdown: "{seconds} 秒后可重新发送",
  resent: "已重新发送，请查收最新的一封",
  hint: "没收到？看看垃圾邮件箱，或确认邮箱地址是否写对",
  failed: "请求失败，请稍后重试",
  success: "登录成功",
  successDescription: "身份验证已完成。",
  alternative: "账号密码登录",
}
type Auth08Labels = typeof DEFAULT_LABELS

/** 输入到「名字@」时给出的常用后缀 */
const DEFAULT_DOMAIN_SUGGESTIONS = [
  "qq.com",
  "163.com",
  "gmail.com",
  "outlook.com",
]

/** 按邮箱域名找网页邮箱入口；不在表里的域名不显示「打开邮箱」按钮 */
const DEFAULT_MAIL_PROVIDERS: Auth08MailProvider[] = [
  {
    name: "QQ 邮箱",
    domains: ["qq.com", "foxmail.com"],
    url: "https://mail.qq.com",
  },
  { name: "163 邮箱", domains: ["163.com"], url: "https://mail.163.com" },
  { name: "126 邮箱", domains: ["126.com"], url: "https://mail.126.com" },
  {
    name: "新浪邮箱",
    domains: ["sina.com", "sina.cn"],
    url: "https://mail.sina.com.cn",
  },
  { name: "Gmail", domains: ["gmail.com"], url: "https://mail.google.com" },
  {
    name: "Outlook",
    domains: ["outlook.com", "hotmail.com", "live.com"],
    url: "https://outlook.live.com",
  },
  {
    name: "iCloud 邮件",
    domains: ["icloud.com", "me.com"],
    url: "https://www.icloud.com/mail",
  },
]

function formatLabel(
  template: string,
  values: Record<string, string | number>,
) {
  return template.replace(/\{(\w+)\}/g, (_, key: string) =>
    String(values[key] ?? ""),
  )
}

/** 传入的表排在默认表之前，同一域名以传入的为准 */
function findMailProvider(email: string, custom: Auth08MailProvider[] = []) {
  const domain = email.slice(email.lastIndexOf("@") + 1).toLowerCase()
  if (!domain) return undefined
  return [...custom, ...DEFAULT_MAIL_PROVIDERS].find((provider) =>
    provider.domains.some((item) => item.toLowerCase() === domain),
  )
}

/** 「名字@」或「名字@q」时返回能补全的后缀；已经写完整域名时返回空数组 */
function matchDomainSuggestions(value: string, suggestions: string[]) {
  const at = value.indexOf("@")
  if (at <= 0 || value.indexOf("@", at + 1) !== -1) return []
  const typed = value.slice(at + 1).toLowerCase()
  if (/\s/.test(value)) return []
  return suggestions.filter(
    (domain) =>
      domain.toLowerCase().startsWith(typed) && domain.toLowerCase() !== typed,
  )
}

export {
  DEFAULT_DOMAIN_SUGGESTIONS,
  DEFAULT_LABELS,
  DEFAULT_MAIL_PROVIDERS,
  findMailProvider,
  formatLabel,
  matchDomainSuggestions,
}
export type { Auth08Labels }

"use client"
import * as React from "react"
/** 用同步锁拦截自动提交与回车的重复请求。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run(action: () => Promise<void>) {
    if (lock.current) return false
    lock.current = true
    setPending(true)
    setError("")
    try {
      await action()
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}
export { useAsyncAction }

"use client"

import type * as React from "react"
import { Button } from "@/components/ui/button"
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"
import { cn } from "@/lib/utils"

function Auth08CodeInput({
  length,
  value,
  error,
  describedBy,
  label,
  disabled,
  onChange,
  onComplete,
}: {
  length: number
  value: string
  error: boolean
  describedBy?: string
  label: string
  disabled: boolean
  onChange: (value: string) => void
  onComplete: (value: string) => void
}) {
  return (
    <div data-slot="auth-08-code-input">
      <InputOTP
        maxLength={length}
        value={value}
        onChange={onChange}
        onComplete={onComplete}
        pattern="^[0-9]*$"
        autoComplete="one-time-code"
        inputMode="numeric"
        aria-label={label}
        aria-invalid={error || undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        containerClassName="w-full"
      >
        <InputOTPGroup className="w-full">
          {Array.from({ length }, (_, index) => (
            <InputOTPSlot
              key={index}
              index={index}
              aria-invalid={error || undefined}
              className="h-9 min-w-0 flex-1 border-edge text-base data-[active=true]:border-foreground/25 data-[active=true]:bg-muted/40 data-[active=true]:ring-0 pointer-coarse:h-11"
            />
          ))}
        </InputOTPGroup>
      </InputOTP>
    </div>
  )
}

/** 邮箱后缀小按钮：按下时不抢走输入框焦点，补全后光标仍在输入框末尾 */
function Auth08DomainSuggestions({
  label,
  local,
  domains,
  disabled,
  onPick,
}: {
  label: string
  local: string
  domains: string[]
  disabled: boolean
  onPick: (email: string) => void
}) {
  if (domains.length === 0) return null
  return (
    <div
      role="group"
      aria-label={label}
      data-slot="auth-08-domain-suggestions"
      className="flex flex-wrap gap-1.5"
    >
      {domains.map((domain) => (
        <Button
          key={domain}
          type="button"
          variant="outline"
          size="sm"
          disabled={disabled}
          aria-label={`${local}@${domain}`}
          className="border-edge font-mono text-xs font-normal text-muted-foreground hover:text-foreground"
          onMouseDown={(event) => event.preventDefault()}
          onClick={() => onPick(`${local}@${domain}`)}
        >
          @{domain}
        </Button>
      ))}
    </div>
  )
}

/** 带文字的分隔线，两侧线条用网格线色 */
function Auth08Divider({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="auth-08-divider"
      className={cn(
        "flex items-center gap-3 text-xs text-muted-foreground before:h-px before:flex-1 before:bg-edge after:h-px after:flex-1 after:bg-edge",
        className,
      )}
      {...props}
    />
  )
}

export { Auth08CodeInput, Auth08DomainSuggestions, Auth08Divider }

"use client"

import * as React from "react"
import { ExternalLink, Mail } from "lucide-react"
import { Button, buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { BarField } from "@/components/ui/bar-field/bar-field"
import { Ripple } from "@/components/ui/ripple/ripple"
import { formatLabel, type Auth08Labels } from "./config"
import {
  Auth08CodeInput,
  Auth08Divider,
  Auth08DomainSuggestions,
} from "./form-parts"
import type { Auth08MailProvider } from "./types"

type TitleRef = React.Ref<HTMLHeadingElement>

const titleClass =
  "text-2xl font-semibold tracking-tight outline-none focus-visible:underline focus-visible:underline-offset-4"

function Auth08EmailStep({
  labels,
  titleRef,
  inputRef,
  email,
  error,
  pending,
  suggestions,
  submitLabel,
  submitDisabled,
  onEmailChange,
  onPick,
  onSubmit,
}: {
  labels: Auth08Labels
  titleRef: TitleRef
  inputRef: React.Ref<HTMLInputElement>
  email: string
  error: string
  pending: boolean
  suggestions: string[]
  submitLabel: string
  submitDisabled: boolean
  onEmailChange: (value: string) => void
  onPick: (value: string) => void
  onSubmit: () => void
}) {
  const id = React.useId()
  const errorId = `${id}-error`
  return (
    <div data-slot="auth-08-email" className="space-y-6">
      <div>
        <h1 ref={titleRef} tabIndex={-1} className={titleClass}>
          {labels.title}
        </h1>
        <p className="mt-2 text-sm leading-7 text-balance text-muted-foreground">
          {labels.description}
        </p>
      </div>
      <form
        noValidate
        className="space-y-5"
        onSubmit={(event) => {
          event.preventDefault()
          onSubmit()
        }}
      >
        <div className="space-y-2">
          <BarField
            inputRef={inputRef}
            label={labels.email}
            type="email"
            name="email"
            autoComplete="email"
            inputMode="email"
            autoCapitalize="none"
            spellCheck={false}
            placeholder={labels.emailPlaceholder}
            size="lg"
            required
            value={email}
            onValueChange={onEmailChange}
            disabled={pending}
            aria-invalid={error ? true : undefined}
            aria-describedby={error ? errorId : undefined}
          />
          {/* 错误不走 BarField 的 error：这里要 role="alert" 让读屏立即播报 */}
          {error && (
            <p
              role="alert"
              id={errorId}
              data-slot="auth-08-email-error"
              className="text-xs text-destructive"
            >
              {error}
            </p>
          )}
          <Auth08DomainSuggestions
            label={labels.suggestions}
            local={email.slice(0, email.indexOf("@"))}
            domains={suggestions}
            disabled={pending}
            onPick={onPick}
          />
        </div>
        <Button
          type="submit"
          size="lg"
          className="w-full"
          disabled={submitDisabled}
        >
          {submitLabel}
        </Button>
      </form>
    </div>
  )
}

function Auth08SentStep({
  labels,
  titleRef,
  email,
  provider,
  showCode,
  codeLength,
  code,
  codeError,
  verifying,
  resendError,
  resendNotice,
  resendLabel,
  resendDisabled,
  pending,
  onCodeChange,
  onCodeComplete,
  onChangeEmail,
  onResend,
}: {
  labels: Auth08Labels
  titleRef: TitleRef
  email: string
  provider?: Auth08MailProvider
  showCode: boolean
  codeLength: number
  code: string
  codeError: string
  verifying: boolean
  resendError: string
  resendNotice: boolean
  resendLabel: string
  resendDisabled: boolean
  pending: boolean
  onCodeChange: (value: string) => void
  onCodeComplete: (value: string) => void
  onChangeEmail: () => void
  onResend: () => void
}) {
  const id = React.useId()
  const [before, after = ""] = labels.sentTo.split("{email}")
  return (
    <div data-slot="auth-08-sent" className="space-y-6">
      <div className="flex flex-col items-center text-center">
        {/* 以邮件图标为圆心向外扩散，表达「已发出」；纯装饰，状态由标题和文字说明 */}
        <Ripple
          size={120}
          rings={3}
          ringGap={28}
          baseSize={44}
          duration={3.5}
          background="dots"
          tone="primary"
          className="h-30 w-56 max-w-full"
        >
          <span className="absolute top-1/2 left-1/2 flex size-11 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-edge bg-background text-primary [&_svg]:size-5">
            <Mail />
          </span>
        </Ripple>
        <h1 ref={titleRef} tabIndex={-1} className={cn("mt-4", titleClass)}>
          {labels.sentTitle}
        </h1>
        <p className="mt-2 text-sm leading-7 text-muted-foreground">
          {before}
          <span
            data-slot="auth-08-sent-email"
            className="font-mono break-all text-foreground"
          >
            {email}
          </span>
          {after} {/* 例外：行内文字链接，高度跟随文字，不占按钮的三档高度 */}
          <Button
            type="button"
            variant="link"
            size="sm"
            disabled={pending}
            className="h-auto px-0 align-baseline text-sm pointer-coarse:h-auto"
            onClick={onChangeEmail}
          >
            {labels.changeEmail}
          </Button>
        </p>
      </div>
      {provider && (
        <a
          href={provider.url}
          target="_blank"
          rel="noreferrer"
          data-slot="auth-08-open-mail"
          className={buttonVariants({ size: "lg", className: "w-full" })}
        >
          {formatLabel(labels.openMail, { name: provider.name })}
          <ExternalLink aria-hidden="true" />
          <span className="sr-only">{labels.newTab}</span>
        </a>
      )}
      {showCode && (
        <div className="space-y-4">
          <Auth08Divider>
            {provider ? labels.codeDivider : labels.codeDividerSolo}
          </Auth08Divider>
          <div className="space-y-2">
            <Auth08CodeInput
              length={codeLength}
              value={code}
              label={formatLabel(labels.code, { length: codeLength })}
              disabled={pending}
              error={!!codeError}
              describedBy={codeError ? `${id}-code-error` : undefined}
              onChange={onCodeChange}
              onComplete={onCodeComplete}
            />
            {codeError ? (
              <p
                role="alert"
                id={`${id}-code-error`}
                data-slot="auth-08-code-error"
                className="text-xs text-destructive"
              >
                {codeError}
              </p>
            ) : (
              // 验证中格子已禁用，视觉上足够；这里只给读屏播报
              <p aria-live="polite" className="sr-only">
                {verifying ? labels.verifying : ""}
              </p>
            )}
          </div>
        </div>
      )}
      <div className="-mt-2 space-y-2 text-center">
        {/* 宽度占满：文案在「重新发送 / 倒计时 / 发送中」之间切换时位置不跳 */}
        <Button
          type="button"
          variant="link"
          className="w-full"
          disabled={resendDisabled}
          onClick={onResend}
        >
          {resendLabel}
        </Button>
        {resendError ? (
          <p
            role="alert"
            data-slot="auth-08-resend-error"
            className="text-xs text-destructive"
          >
            {resendError}
          </p>
        ) : (
          <p
            role="status"
            className="text-xs text-muted-foreground empty:hidden"
          >
            {resendNotice ? labels.resent : ""}
          </p>
        )}
        <p className="text-xs leading-5 text-muted-foreground">{labels.hint}</p>
      </div>
    </div>
  )
}

export { Auth08EmailStep, Auth08SentStep }
